package br.mareeletrica;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.EmptyBlockGetter;
import net.minecraft.world.level.block.state.BlockState;
/** Server-authoritative persistent paint and geometry, bounded before committing an edit. */
public final class ProjectionEditor {
 public static final int[] COLORS={0xEEEDE5,0xED8533,0xBB52BF,0x64B8E5,0xE9D437,0x80BC35,0xEC95B6,0x42464C,0x989E9F,0x198E9D,0x8545B7,0x354CAC,0x865B3A,0x56772A,0xB43832,0x20252C,0x4CCDF0};
 public int width,height,depth,revision;
 private final Map<Integer,Integer> paint=new HashMap<>();private ProjectionPlans.Plan cached;private int blueprint=-1;
 public void reset(){width=height=depth=0;paint.clear();cached=null;revision++;}
 public static int color(BlockState s){int rgb=s.getMapColor(EmptyBlockGetter.INSTANCE,BlockPos.ZERO).col;if(rgb==0)rgb=0x7EAEC5;int best=0,score=Integer.MAX_VALUE;for(int i=0;i<16;i++){int c=COLORS[i],r=(rgb>>16&255)-(c>>16&255),g=(rgb>>8&255)-(c>>8&255),b=(rgb&255)-(c&255),n=r*r+g*g+b*b;if(n<score){score=n;best=i;}}return best;}
 public int color(ProjectionPlans.Cell c){return paint.getOrDefault(VoxelRules.key(c.pos().getX(),c.pos().getY(),c.pos().getZ()),color(c.original()));}
 public ProjectionPlans.Plan plan(MachineEntity m){if(cached!=null&&blueprint==m.blueprint)return cached;var base=ProjectionPlans.get((ServerLevel)m.getLevel(),m.blueprint);if(base.cells().isEmpty())return base;if(!VoxelRules.validSize(width,height,depth)){width=base.width();height=base.height();depth=base.depth();}try{cached=scale(base,width,height,depth);}catch(IllegalArgumentException ex){reset();width=base.width();height=base.height();depth=base.depth();cached=base;}blueprint=m.blueprint;return cached;}
 private static ProjectionPlans.Plan scale(ProjectionPlans.Plan base,int w,int h,int d){Map<Integer,BlockState> source=new HashMap<>();for(var c:base.cells())source.put(VoxelRules.key(c.pos().getX(),c.pos().getY(),c.pos().getZ()),c.original());List<ProjectionPlans.Cell> cells=new ArrayList<>();for(int y=0;y<h;y++)for(int z=0;z<d;z++)for(int x=0;x<w;x++){var s=source.get(VoxelRules.key(VoxelRules.sample(x,base.width(),w),VoxelRules.sample(y,base.height(),h),VoxelRules.sample(z,base.depth(),d)));if(s!=null){if(cells.size()>=VoxelRules.MAX_CELLS)throw new IllegalArgumentException();cells.add(new ProjectionPlans.Cell(new BlockPos(x,y,z),s));}}return new ProjectionPlans.Plan(w,h,d,List.copyOf(cells));}
 public boolean resize(MachineEntity m,int w,int h,int d){if(!VoxelRules.validSize(w,h,d))return false;var old=plan(m);ProjectionPlans.Plan next;try{next=scale(ProjectionPlans.get((ServerLevel)m.getLevel(),m.blueprint),w,h,d);}catch(IllegalArgumentException ex){return false;}Map<Integer,Integer> colors=new HashMap<>();for(var c:next.cells()){int k=VoxelRules.key(VoxelRules.sample(c.pos().getX(),old.width(),w),VoxelRules.sample(c.pos().getY(),old.height(),h),VoxelRules.sample(c.pos().getZ(),old.depth(),d));if(paint.containsKey(k))colors.put(VoxelRules.key(c.pos().getX(),c.pos().getY(),c.pos().getZ()),paint.get(k));}ConstructionProjector.stop(m);width=w;height=h;depth=d;cached=next;paint.clear();paint.putAll(colors);revision++;m.setChanged();return true;}
 public boolean paint(MachineEntity m,int key,int color,boolean material){if(color<0||color>=COLORS.length)return false;var p=plan(m);var selected=p.cells().stream().filter(c->VoxelRules.key(c.pos().getX(),c.pos().getY(),c.pos().getZ())==key).findFirst();if(selected.isEmpty())return false;ConstructionProjector.stop(m);for(var c:p.cells())if(material?c.original().getBlock()==selected.get().original().getBlock():c==selected.get())paint.put(VoxelRules.key(c.pos().getX(),c.pos().getY(),c.pos().getZ()),color);revision++;m.setChanged();return true;}
 public boolean paintBatch(MachineEntity m,int[] keys,int color){if(keys.length==0||keys.length>128||color<0||color>=COLORS.length)return false;Set<Integer> wanted=new HashSet<>();for(int k:keys)wanted.add(k);boolean changed=false;for(var cell:plan(m).cells()){int k=VoxelRules.key(cell.pos().getX(),cell.pos().getY(),cell.pos().getZ());if(wanted.contains(k)&&color(cell)!=color){paint.put(k,color);changed=true;}}if(changed){ConstructionProjector.stop(m);revision++;m.setChanged();}return true;}
 public CompoundTag save(){var t=new CompoundTag();t.putInt("Width",width);t.putInt("Height",height);t.putInt("Depth",depth);int[] a=new int[paint.size()*2];int i=0;for(var e:paint.entrySet()){a[i++]=e.getKey();a[i++]=e.getValue();}t.putIntArray("Paint",a);return t;}
 public void load(CompoundTag t){reset();width=t.getInt("Width");height=t.getInt("Height");depth=t.getInt("Depth");int[] a=t.getIntArray("Paint");for(int i=0;i+1<a.length&&paint.size()<VoxelRules.MAX_CELLS;i+=2)if(a[i]>=0&&a[i]<(1<<21)&&a[i+1]>=0&&a[i+1]<COLORS.length)paint.put(a[i],a[i+1]);}
}
